// ui.js: page helpers shared by final.js. Students do NOT edit this file.
const fs = require("fs");
const path = require("path");
const CSS = fs.readFileSync(path.join(__dirname, "style.css"), "utf8");

const esc = (t) => String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

// Grey box for a step that is not done, red box for a step with an error
function box(s) {
  if (s.status === "error") return `<div class="error">🔴 Step ${s.n} (${s.file}) has an error: ${esc(s.err)}</div>`;
  const d3 = s.day === 3;
  return `<div class="todo${d3 ? " d3" : ""}">⬜ <b>Step ${s.n}: ${s.title}</b>${d3 ? " · Day 3" : ""} · not done yet · open <code>${s.file}</code></div>`;
}

// Run the student's function if the step is done, else show the grey box
function part(s, ...args) {
  if (s.status !== "done") return box(s);
  try {
    return s.f(...args);
  } catch (e) {
    return `<div class="error">🔴 Step ${s.n}: ${esc(e.name + ": " + e.message)}</div>`;
  }
}

function page(app, S, inner) {
  const all = Object.values(S);
  const done = all.filter((s) => s.status === "done").length;
  const chips = all.map((s) => `<span class="${s.status === "done" ? "ok" : s.status === "error" ? "err" : ""}">${s.status === "done" ? "✅" : s.status === "error" ? "🔴" : "⬜"} ${s.n}</span>`).join("");
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${app}</title><style>${CSS}</style></head><body><div class="wrap">
<div class="top"><div><b>ILP WORKSHOP</b><div>${app}</div></div>
<div class="prog"><small>${done} / ${all.length} steps done</small><div class="bar"><i style="width:${Math.round((done * 100) / all.length)}%"></i></div></div></div>
<div class="steps">${chips}</div>
${inner}
</div></body></html>`;
}

module.exports = { esc, box, part, page };
